import numpy as np

def select_next_node(current_node, truck_nodes, depot_node, unvisited_nodes, distance_matrix):
    # { From the current node, select the closest unvisited node that is not already the target of another truck; if none are available, return the depot when all nodes are visited, otherwise wait (return None). }

    if len(unvisited_nodes) == 0:
        return depot_node

    # Build set of nodes other trucks are heading to (or already at)
    truck_targets = set()
    for t in truck_nodes:
        if t is not None:
            truck_targets.add(t)

    # Distances from current node to all unvisited nodes
    distances = distance_matrix[current_node, unvisited_nodes]

    # Sort unvisited nodes by distance (ascending)
    sorted_indices = np.argsort(distances)

    # Select the closest node not already targeted
    for idx in sorted_indices:
        candidate = unvisited_nodes[idx]
        if candidate not in truck_targets:
            return candidate

    # All candidates are already targeted -> wait
    return next_node
